def parse_sort_choice(val: str) -> str:
    """Normalize and map CLI --sort choice values and aliases."""
    if not isinstance(val, str):
        return val
    v = val.lower()
    return SORT_ALIASES.get(v, v)


def parse_format_choice(val: str) -> str:
    """Normalize and map CLI --format choice values and aliases."""
    if not isinstance(val, str):
        return val
    v = val.lower()
    return FORMAT_ALIASES.get(v, v)


def parse_preset_choice(val: str) -> str:
    """Normalize and map CLI --preset choice values and aliases."""
    if not isinstance(val, str):
        return val
    v = val.strip()
    if v == "-A":
        return "analyze"
    v_lower = v.lower()
    return PRESET_ALIASES.get(v_lower, v_lower)


class ColoredArgumentParser(argparse.ArgumentParser):
    """Custom ArgumentParser to provide rich error colors and intelligent spelling suggestions."""

    def error(self, message):
        import difflib
        import re

        # Build list of valid option strings
        valid_options = []
        for action in self._actions:
            valid_options.extend(action.option_strings)

        # Check for unrecognized arguments typo
        if "unrecognized arguments" in message:
            parts = message.split("unrecognized arguments:", 1)
            if len(parts) == 2:
                unrecognized_parts = parts[1].strip().split()
                suggestions = []
                for arg in unrecognized_parts:
                    matches = difflib.get_close_matches(arg, valid_options, n=3, cutoff=0.6)
                    if matches:
                        colored_matches = ", ".join(f"{C_BOLD:only_stderr}{C_GREEN:only_stderr}{m}{C_RESET:only_stderr}" for m in matches)
                        suggestions.append(f"  {C_BOLD:only_stderr}{C_RED:only_stderr}{arg}{C_RESET:only_stderr} -> did you mean: {colored_matches}?")
                if suggestions:
                    message += f"\n\n{C_BOLD:only_stderr}{C_CYAN:only_stderr}Suggestions:{C_RESET:only_stderr}\n" + "\n".join(suggestions)

        # Check for invalid choice errors
        elif "invalid choice:" in message:
            for action in self._actions:
                if (not action.option_strings or any(opt in message for opt in action.option_strings)) and action.choices:
                    m = re.search(r"invalid choice:\s*'?([^'\s,]+)'?", message)
                    if m:
                        invalid_val = m.group(1)
                        choices_list = [str(c) for c in action.choices]
                        matches = difflib.get_close_matches(invalid_val, choices_list, n=3, cutoff=0.5)
                        if matches:
                            colored_matches = ", ".join(f"{C_BOLD:only_stderr}{C_GREEN:only_stderr}{m}{C_RESET:only_stderr}" for m in matches)
                            suggestion = f"  {C_BOLD:only_stderr}{C_RED:only_stderr}{invalid_val}{C_RESET:only_stderr} -> Did you mean: {colored_matches}?"
                            message += f"\n\n{C_BOLD:only_stderr}{C_CYAN:only_stderr}Suggestions:{C_RESET:only_stderr}\n{suggestion}"
                    break

        # Display usage to stderr
        self.print_usage(sys.stderr)
        # Apply bold and red coloring to error header
        error_label = f"{C_BOLD}{C_RED}error:{C_RESET}"
        self.exit(2, f"{self.prog}: {error_label} {message}\n")


