    if getattr(args, 'project_info', None) is True:
        # We need to load and validate config first to get root folders and information overrides
        targets = args.targets
        config_path = args.config
        remaining_targets = []
        if targets:
            first = targets[0]
            is_config_ext = first.lower().endswith(('.yml', '.yaml')) or (
                first.lower().endswith('.json') and not args.extract and not getattr(args, 'verify', False)
            )
            if not config_path and is_config_ext and not Path(first).is_dir():
                config_path = first
                remaining_targets = targets[1:]
            else:
                remaining_targets = targets
        if not config_path:
            defaults = [
                'sourcecombine.yml', 'sourcecombine.yaml',
                'sourcecombine.json',
                'config.yml', 'config.yaml',
                'config.json'
            ]
            for d in defaults:
                if Path(d).is_file():
                    config_path = d
                    break
        try:
            if config_path:
                config = load_and_validate_config(config_path)
            else:
                config = copy.deepcopy(utils.DEFAULT_CONFIG)
                utils.validate_config(config)
        except (ConfigNotFoundError, utils.InvalidConfigError) as e:
            _handle_invalid_config_error(e, args.verbose)

        if remaining_targets:
            config['search']['root_folders'] = remaining_targets
        elif not config.get('search', {}).get('root_folders'):
            config.setdefault('search', {})['root_folders'] = ["."]

        _apply_project_overrides(config, args)

        stats = {}
        root = config['search']['root_folders'][0]
        _populate_project_stats(stats, root, config)
        git_info = _get_git_info(root, log_count=config['output'].get('git_log_count', 0), include_diff=config['output'].get('include_diff', False))
        stats.update(git_info)

        print_project_info(stats, json_format=getattr(args, 'json', False))
        sys.exit(0)

    if args.list_placeholders:
        query = args.list_placeholders if isinstance(args.list_placeholders, str) else None
        print_placeholders(query=query, json_format=getattr(args, 'json', False))
        sys.exit(0)

    list_fmt_val = getattr(args, 'list_formats', False)
    if list_fmt_val and type(list_fmt_val).__name__ in ('MagicMock', 'Mock', 'NonCallableMagicMock'):
        list_fmt_val = False

    if list_fmt_val:
        query = list_fmt_val if isinstance(list_fmt_val, str) else None
        print_formats(query=query, json_format=getattr(args, 'json', False))
        sys.exit(0)

    list_pre_val = getattr(args, 'list_presets', False)
