def _parse_json_entry(entry: dict) -> tuple[str, Any, dict]:
    """Extract (path, content, meta) tuple from a parsed JSON entry dictionary."""
    meta = {
        'tokens': _to_int_or_none(entry.get('tokens')),
        'size': _to_int_or_none(entry.get('size_bytes')),
        'lines': _to_int_or_none(entry.get('lines')),
        'is_approx': entry.get('tokens_is_approx', False),
        'modified': entry.get('modified'),
        'sha256': entry.get('sha256'),
        'language': entry.get('language'),
    }
    return entry['path'], entry.get('content'), meta


def _parse_combined_content(content, source_name="combined file"):
    """Identify and parse combined file content into a list of (path, content, meta) tuples."""
    if not content:
        return []

    files_found = []

    # 1. Try JSON
    try:
        data = json.loads(content)
        if isinstance(data, list):
            for entry in data:
                if isinstance(entry, dict) and 'path' in entry:
                    files_found.append(_parse_json_entry(entry))
            if files_found:
                return files_found
    except json.JSONDecodeError:
        pass

    # 1.5 Try JSONL if JSON failed
    potential_files = []
    for line in content.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            entry = json.loads(line)
            if isinstance(entry, dict) and 'path' in entry:
                potential_files.append(_parse_json_entry(entry))
            else:
                logging.debug("Skipping malformed JSONL line in %s: %s", source_name, line)
        except (json.JSONDecodeError, TypeError):
            pass

    if potential_files:
        return potential_files

    # 2. Try XML
    try:
        root = ET.fromstring(content)
        # Support both flat and nested <file> tags
        for file_node in root.iter('file'):
            try:
                path = file_node.get('path')
                file_content = file_node.text or ""
                if path:
                    # XML extraction often has extra newlines due to templates
                    if file_content and file_content.startswith('\n') and file_content.endswith('\n'):
                        file_content = file_content[1:-1]

                    tokens_val = file_node.get('tokens')
                    size_val = file_node.get('size')
                    lines_val = file_node.get('lines')
                    mod_val = file_node.get('modified')
                    sha_val = file_node.get('sha256')
                    lang_val = file_node.get('language')

                    tokens = _to_int_or_none(tokens_val)
                    size = utils.parse_size_value(size_val) if size_val else None
                    is_approx = False
                    if tokens_val and str(tokens_val).strip().startswith('~'):
                        is_approx = True
                    if size_val and str(size_val).strip().startswith('~'):
                        is_approx = True

                    meta = {
                        'tokens': tokens,
                        'size': size,
                        'lines': _to_int_or_none(lines_val),
                        'is_approx': is_approx,
                        'modified': datetime.fromisoformat(mod_val).timestamp() if mod_val else None,
                        'sha256': sha_val,
                        'language': lang_val,
                    }
                    files_found.append((path, file_content, meta))
            except (ValueError, TypeError, AttributeError) as exc:
                logging.debug("Skipping malformed XML file entry: %s", exc)
                continue

        if files_found:
            return files_found
    except (ET.ParseError, ImportError):
        pass

    # 2.5 Try CSV
    if content.startswith("path,size_bytes,tokens,"):
        try:
            reader = csv.DictReader(io.StringIO(content))
            for row in reader:
                if row.get("path"):
                    meta = {
                        'tokens': _to_int_or_none(row.get('tokens')),
                        'size': _to_int_or_none(row.get('size_bytes')),
                        'lines': _to_int_or_none(row.get('lines')),
                        'is_approx': row.get('tokens_is_approx') == 'True',
                        'modified': float(row['modified']) if row.get('modified') else None,
                        'sha256': row.get('sha256'),
                        'language': row.get('language'),
                    }
                    files_found.append((row['path'], row.get('content'), meta))
            if files_found:
                return files_found
        except (csv.Error, ValueError, KeyError):
            pass

    # 3. Try Text format (Default SourceCombine output)
    pattern = re.compile(r'^---\s+(.+?)\s+---\n([\s\S]*?)\n--- end \1 ---', re.MULTILINE)
    for match in pattern.finditer(content):
        path, file_content = match.groups()
        files_found.append((path.strip(), file_content, {}))
    if files_found:
        return files_found

    # 4. Try Markdown
    collapsible_pattern = re.compile(
        r'<details>\s*<summary>(.*?)</summary>([\s\S]*?)</details>',
        re.IGNORECASE | re.MULTILINE
    )
    for match in collapsible_pattern.finditer(content):
        summary_content, block_content = match.groups()
        # Find the path inside <b>...</b>, or fallback to text content inside <summary>
        path_match = re.search(r'<b>\s*([^<]+?)\s*</b>', summary_content)
        if path_match:
            path = path_match.group(1)
        else:
            path = re.sub(r'<[^>]+>', '', summary_content).strip()
            # If there is parenthesis or details, strip them
            if ' (' in path:
                path = path.split(' (')[0].strip()

        # Find if there is a code block inside
        cb_match = re.search(r'```(?:\S+)?\n([\s\S]*?)\n^```', block_content, re.MULTILINE)
        if cb_match:
            file_content = cb_match.group(1)
        else:
            file_content = block_content.strip()
        files_found.append((path.strip(), file_content, {}))

    if files_found:
        return files_found

    code_block_pattern = re.compile(r'^```(?:\S+)?\n([\s\S]*?)\n^```', re.MULTILINE)
    header_pattern = re.compile(r'^#{2,3}\s+(.+?)\s*$', re.MULTILINE)

    last_pos = 0
    for cb_match in code_block_pattern.finditer(content):
        search_space = content[last_pos:cb_match.start()]
        h_matches = list(header_pattern.finditer(search_space))
        if h_matches:
            path = h_matches[-1].group(1).strip()
            file_content = cb_match.group(1)
            files_found.append((path, file_content, {}))
        last_pos = cb_match.end()

    return files_found


def verify_files(sources, root_folder=".", config=None, show_diff=False, repair=False, dry_run=False, strip_components=0, json_format=False, quiet=False):
    """Verify that files on disk match the manifest or combined file."""
    root_folder = Path(root_folder)
    if config is None:
        config = copy.deepcopy(utils.DEFAULT_CONFIG)

    create_backups = False
    if config and config.get('processing'):
        create_backups = bool(config['processing'].get('create_backups', False))

    files_to_verify = []
    for name, content in sources:
        found = _parse_combined_content(content, source_name=name)
        if not found:
            logging.warning("No files found to verify in %s.", name)
        files_to_verify.extend(found)

    if not files_to_verify:
        logging.error("No files found to verify in any of the sources.")
        sys.exit(1)

    # Apply configuration filters using should_include
    filter_opts = config.get('filters', {})
    search_opts = config.get('search', {})
    filtered_files = []
    for rel_path_str, expected_content, meta in files_to_verify:
        rel_path = PurePath(rel_path_str)
        include = should_include(
            None,
            rel_path,
            filter_opts,
            search_opts,
            virtual_content=expected_content,
        )
        if include:
            filtered_files.append((rel_path_str, expected_content, meta))
    files_to_verify = filtered_files

    title = "Repair Report" if repair else "Verification Report"
    if not json_format:
        print(f"\n{C_BOLD}{C_CYAN}=== {title.upper()} ==={C_RESET}")
    json_results = []

    matches = 0
    mismatches = 0
    missing = 0
    repaired = 0
    total = len(files_to_verify)

    show_progress = not json_format and _progress_enabled(dry_run)
    verification_bar = _progress_bar(
        files_to_verify,
        desc="Repairing files" if repair else "Verifying files",
        unit="file",
        enabled=show_progress
    )

    def _write_msg(msg, is_error=False):
        if not json_format and (not quiet or is_error):
            if show_progress and hasattr(verification_bar, "write"):
                verification_bar.write(msg, file=sys.stdout)
            else:
                print(msg)

    def _update_stats(matches_inc=0, mismatches_inc=0, missing_inc=0, repaired_inc=0):
        nonlocal matches, mismatches, missing, repaired
        matches += matches_inc
        mismatches += mismatches_inc
        missing += missing_inc
        repaired += repaired_inc
        if show_progress:
            verification_bar.set_postfix(
                ok=matches,
                mismatch=mismatches,
                missing=missing,
                repaired=repaired
            )

    try:
        for rel_path_str, expected_content, meta in verification_bar:
            # Safety check: prevent path traversal (similar to extract_files)
            try:
                requested_path = Path(rel_path_str)

                if strip_components > 0:
                    parts = requested_path.parts
                    if len(parts) <= strip_components:
                        logging.warning("Skipping path with fewer than %d components: %s", strip_components, rel_path_str)
                        continue
                    requested_path = Path(*parts[strip_components:])
                if requested_path.is_absolute() or PurePosixPath(rel_path_str).is_absolute() or PureWindowsPath(rel_path_str).is_absolute() or '..' in requested_path.parts or ':' in rel_path_str:
                    logging.warning("Skipping unsafe path: %s", rel_path_str)
                    continue
                target_path = (root_folder / requested_path).resolve()
            except (ValueError, OSError):
                logging.warning("Skipping invalid path: %s", rel_path_str)
                continue

            if not target_path.exists():
                if repair and expected_content is not None:
                    if dry_run:
                        if json_format:
                            json_results.append({"path": rel_path_str, "status": "REPAIR", "detail": "would create missing file"})
                        else:
                            _write_msg(f"  {C_CYAN}{'[REPAIR]':<10}{C_RESET}  {rel_path_str} {C_DIM}(would create missing file){C_RESET}")
                        _update_stats(repaired_inc=1)
                    else:
                        try:
                            target_path.parent.mkdir(parents=True, exist_ok=True)
                            target_path.write_text(expected_content, encoding='utf-8')
                            if meta.get('modified') is not None:
                                os.utime(target_path, (meta['modified'], meta['modified']))
                            if json_format:
                                json_results.append({"path": rel_path_str, "status": "REPAIRED", "detail": "created missing file"})
                            else:
                                _write_msg(f"  {C_GREEN}{'[REPAIRED]':<10}{C_RESET}  {rel_path_str} {C_DIM}(created missing file){C_RESET}")
                            _update_stats(repaired_inc=1)
                        except OSError as e:
                            if json_format:
                                json_results.append({"path": rel_path_str, "status": "ERROR", "detail": f"failed to repair: {e}"})
                            else:
                                _write_msg(f"  {C_RED}{'[ERROR]':<10}{C_RESET}  {rel_path_str} {C_DIM}(failed to repair: {e}){C_RESET}")
                            _update_stats(missing_inc=1)
                else:
                    if json_format:
                        json_results.append({"path": rel_path_str, "status": "MISSING", "detail": "missing file"})
                    else:
                        _write_msg(f"  {C_RED}{'[MISSING]':<10}{C_RESET}  {rel_path_str}", is_error=True)
                    _update_stats(missing_inc=1)
                continue

            # Priority 1: Check SHA-256 if available in information
            expected_sha = meta.get('sha256')
            if expected_sha:
                try:
                    actual_sha = _get_sha256_hash(target_path.read_bytes())
                    if actual_sha == expected_sha:
                        if json_format:
                            json_results.append({"path": rel_path_str, "status": "OK", "detail": "hash match"})
                        else:
                            _write_msg(f"  {C_GREEN}{'[OK]':<10}{C_RESET}  {rel_path_str} {C_DIM}(hash match){C_RESET}")
                        _update_stats(matches_inc=1)
                    else:
                        if repair and expected_content is not None:
                            if dry_run:
                                if json_format:
                                    json_results.append({"path": rel_path_str, "status": "REPAIR", "detail": "would fix hash mismatch"})
                                else:
                                    _write_msg(f"  {C_CYAN}{'[REPAIR]':<10}{C_RESET}  {rel_path_str} {C_DIM}(would fix hash mismatch){C_RESET}")
                                _update_stats(repaired_inc=1)
                            else:
                                try:
                                    _create_backup_if_enabled(target_path, create_backups)
                                    target_path.write_text(expected_content, encoding='utf-8')
                                    if meta.get('modified') is not None:
                                        os.utime(target_path, (meta['modified'], meta['modified']))
                                    if json_format:
                                        json_results.append({"path": rel_path_str, "status": "REPAIRED", "detail": "fixed hash mismatch"})
                                    else:
                                        _write_msg(f"  {C_GREEN}{'[REPAIRED]':<10}{C_RESET}  {rel_path_str} {C_DIM}(fixed hash mismatch){C_RESET}")
                                    _update_stats(repaired_inc=1)
                                except OSError as e:
                                    if json_format:
                                        json_results.append({"path": rel_path_str, "status": "ERROR", "detail": f"failed to repair: {e}"})
                                    else:
                                        _write_msg(f"  {C_RED}{'[ERROR]':<10}{C_RESET}  {rel_path_str} {C_DIM}(failed to repair: {e}){C_RESET}")
                                    _update_stats(mismatches_inc=1)
                        else:
                            if json_format:
                                json_results.append({"path": rel_path_str, "status": "MISMATCH", "detail": "hash mismatch"})
                            else:
                                _write_msg(f"  {C_RED}{'[MISMATCH]':<10}{C_RESET}  {rel_path_str} {C_DIM}(hash mismatch){C_RESET}", is_error=True)
                            _update_stats(mismatches_inc=1)
                            if show_diff and expected_content is not None:
                                actual_content, _ = read_file_best_effort(target_path)
                                _print_diff(actual_content, expected_content, rel_path_str)
                except OSError as e:
                    if json_format:
                        json_results.append({"path": rel_path_str, "status": "ERROR", "detail": str(e)})
                    else:
                        _write_msg(f"  {C_RED}{'[ERROR]':<10}{C_RESET}  {rel_path_str} {C_DIM}({e}){C_RESET}")
                    _update_stats(mismatches_inc=1)
                continue

            # Priority 2: Check content if available
            if expected_content is not None:
                actual_content, _ = read_file_best_effort(target_path)
                # Normalize line endings for consistent cross-platform content comparison
                if actual_content.replace('\r\n', '\n') == expected_content.replace('\r\n', '\n'):
                    if json_format:
                        json_results.append({"path": rel_path_str, "status": "OK", "detail": "content match"})
                    else:
                        _write_msg(f"  {C_GREEN}{'[OK]':<10}{C_RESET}  {rel_path_str} {C_DIM}(content match){C_RESET}")
                    _update_stats(matches_inc=1)
                else:
                    if repair:
                        if dry_run:
                            if json_format:
                                json_results.append({"path": rel_path_str, "status": "REPAIR", "detail": "would fix content mismatch"})
                            else:
                                _write_msg(f"  {C_CYAN}{'[REPAIR]':<10}{C_RESET}  {rel_path_str} {C_DIM}(would fix content mismatch){C_RESET}")
                            _update_stats(repaired_inc=1)
                        else:
                            try:
                                _create_backup_if_enabled(target_path, create_backups)
                                target_path.write_text(expected_content, encoding='utf-8')
                                if meta.get('modified') is not None:
                                    os.utime(target_path, (meta['modified'], meta['modified']))
                                if json_format:
                                    json_results.append({"path": rel_path_str, "status": "REPAIRED", "detail": "fixed content mismatch"})
                                else:
                                    _write_msg(f"  {C_GREEN}{'[REPAIRED]':<10}{C_RESET}  {rel_path_str} {C_DIM}(fixed content mismatch){C_RESET}")
                                _update_stats(repaired_inc=1)
                            except OSError as e:
                                if json_format:
                                    json_results.append({"path": rel_path_str, "status": "ERROR", "detail": f"failed to repair: {e}"})
                                else:
                                    _write_msg(f"  {C_RED}{'[ERROR]':<10}{C_RESET}  {rel_path_str} {C_DIM}(failed to repair: {e}){C_RESET}")
                                mismatches_inc = 1
                                _update_stats(mismatches_inc=1)
                    else:
                        if json_format:
                            json_results.append({"path": rel_path_str, "status": "MISMATCH", "detail": "content mismatch"})
                        else:
                            _write_msg(f"  {C_RED}{'[MISMATCH]':<10}{C_RESET}  {rel_path_str} {C_DIM}(content mismatch){C_RESET}", is_error=True)
                        _update_stats(mismatches_inc=1)
                        if show_diff:
                            _print_diff(actual_content, expected_content, rel_path_str)
                continue

            if json_format:
                json_results.append({"path": rel_path_str, "status": "SKIPPED", "detail": "no hash or content to verify against"})
            else:
                _write_msg(f"  {C_YELLOW}{'[SKIPPED]':<10}{C_RESET}  {rel_path_str} {C_DIM}(no hash or content to verify against){C_RESET}")
    finally:
        verification_bar.close()

    if json_format:
        output = {
            "title": title,
            "files": json_results,
            "summary": {
                "matches": matches,
                "mismatches": mismatches,
                "missing": missing,
                "repaired": repaired,
                "total": total
            }
        }
        print(json.dumps(output, indent=2))
    elif not quiet or (mismatches > 0 or missing > 0 or repaired > 0):
        print(f"\n{C_BOLD}Summary:{C_RESET}")
        print(f"  Matches:    {C_GREEN if matches == total else C_RESET}{matches}/{total}{C_RESET}")
        if repaired:
            print(f"  Repaired:   {C_GREEN}{repaired}{C_RESET}")
        if mismatches:
            print(f"  Mismatches: {C_RED}{mismatches}{C_RESET}")
        if missing:
            print(f"  Missing:    {C_RED}{missing}{C_RESET}")
        print(f"{C_BOLD}{C_CYAN}{'=' * 27}{C_RESET}\n")

    return {
        'matches': matches,
        'mismatches': mismatches,
        'missing': missing,
        'repaired': repaired,
        'total': total
    }


def extract_files(sources, output_folder, dry_run=False, source_name="combined file", config=None, list_files=False, tree_view=False, limit=0, estimate_tokens=False, sort_by='name', sort_reverse=False, keep_line_numbers=False, show_diff=False, strip_components=0, json_format=False):
    """Recreate the original folder structure and files from combined content sources."""
    output_folder = Path(output_folder)

    if config is None:
        config = copy.deepcopy(utils.DEFAULT_CONFIG)

    create_backups = False
    if config and config.get('processing'):
        create_backups = bool(config['processing'].get('create_backups', False))

    stats = {
        'total_discovered': 0,
        'total_files': 0,
        'total_size_bytes': 0,
        'size_by_extension': {},
        'files_by_language': {},
        'size_by_language': {},
        'total_lines': 0,
        'total_tokens': 0,
        'tokens_by_extension': {},
        'lines_by_extension': {},
        'tokens_by_language': {},
        'lines_by_language': {},
        'custom_languages': config.get('search', {}).get('custom_languages', {}),
        'token_count_is_approx': False,
        'top_files': [],
        'files_by_extension': {},
        'max_files': limit,
        'max_total_tokens': config.get('filters', {}).get('max_total_tokens', 0),
        'max_total_size_bytes': config.get('filters', {}).get('max_total_size_bytes', 0),
        'max_total_lines': config.get('filters', {}).get('max_total_lines', 0),
        'filter_reasons': {},
    }

    # Handle backward compatibility for single source string/bytes
    if isinstance(sources, (str, bytes)):
        sources = [(source_name, sources)]

    if not sources:
        logging.error("No extraction sources provided.")
        sys.exit(1)

    files_to_create = []
    for name, content in sources:
        found = _parse_combined_content(content, source_name=name)
        if not found:
            logging.warning("Could not find any files to extract in %s.", name)
        files_to_create.extend(found)

    if not files_to_create:
        logging.error("Could not find any files to extract in any of the sources.")
        sys.exit(1)

    # Gather project information for templates
    _populate_project_stats(stats, output_folder, config)

    stats['total_discovered'] = len(files_to_create)
    filter_opts = config.get('filters', {})
    search_opts = config.get('search', {})

    filtered_files = []
    for path_str, file_content, meta in files_to_create:
        rel_path = PurePath(path_str)


        # Automatically remove line numbers unless requested otherwise
        if not keep_line_numbers and file_content is not None:
            file_content = utils.remove_line_numbers(file_content)

        # Apply processing rules if any are configured
        processing_opts = config.get('processing', {})
        if processing_opts and file_content is not None:
            lang = utils.get_language_tag(rel_path, content=file_content, overrides=config.get('search', {}).get('custom_languages'))
            processed_content = utils.process_content(file_content, processing_opts, language=lang)
            if processed_content != file_content:
                file_content = processed_content
                # Clear metrics information as it's no longer accurate for the processed content
                meta.pop('size', None)
                meta.pop('tokens', None)
                meta.pop('lines', None)
                meta.pop('is_approx', None)


        include, reason = should_include(
            None,
            rel_path,
            filter_opts,
            search_opts,
            return_reason=True,
            virtual_content=file_content,
        )

        if include:
            filtered_files.append((path_str, file_content, meta))
        else:
            if reason:
                stats['filter_reasons'][reason] = stats['filter_reasons'].get(reason, 0) + 1

    # Content-based deduplication for extraction
    if filter_opts.get('unique'):
        seen_hashes = set()
        unique_files = []
        for path_str, file_content, meta in filtered_files:
            content_hash = _get_sha256_hash(file_content) if file_content is not None else None
            if content_hash and content_hash in seen_hashes:
                logging.debug("Skipping duplicate content in extraction: %s", path_str)
                stats['filter_reasons']['duplicate_content'] = stats['filter_reasons'].get('duplicate_content', 0) + 1
                continue
            seen_hashes.add(content_hash)
            unique_files.append((path_str, file_content, meta))
        filtered_files = unique_files

    # Initial information calculation needed for sorting and limits
    for path_str, file_content, meta in filtered_files:
        if meta.get('size') is None:
            meta['size'] = len(file_content.encode('utf-8')) if file_content is not None else 0
        if meta.get('lines') is None:
            meta['lines'] = utils.count_lines(file_content) if file_content is not None else 0

    # Token Estimation Pass (needed before global limits if sorting by tokens or requested)
    if estimate_tokens or sort_by == 'tokens' or stats['max_total_tokens'] > 0:
        needs_estimation = [f for f in filtered_files if f[1] is not None and f[2].get('tokens') is None]
        if needs_estimation:
            est_bar = _progress_bar(
                needs_estimation,
                desc="Estimating tokens",
                unit="file",
                enabled=_progress_enabled(False)
            )
            running_tokens = 0
            running_lines = 0
            running_size = 0
            for path_str, file_content, meta in est_bar:
                est_bar.set_description(f"Estimating {_truncate_path(path_str, 40)}")
                tokens, is_approx = utils.estimate_tokens(file_content) if file_content is not None else (0, False)
                meta['tokens'] = tokens
                meta['is_approx'] = is_approx
                running_tokens += tokens
                running_lines += meta.get('lines', 0)
                running_size += (meta.get('size') or 0)
                est_bar.set_postfix(size=utils.format_size(running_size), lines=f"{running_lines:,}", tokens=f"{running_tokens:,}")
            est_bar.close()

    # Global Sort
    if sort_by != 'name' or sort_reverse:
        def get_extract_sort_key(item):
            path_str, file_content, meta = item
            if sort_by == 'size':
                val = meta['size']
            elif sort_by == 'tokens':
                val = meta.get('tokens', 0)
            elif sort_by == 'lines':
                val = meta.get('lines', 0)
            elif sort_by == 'modified':
                val = meta.get('modified', 0)
            elif sort_by == 'language':
                val = utils.get_language_tag(path_str, content=file_content, overrides=config.get('search', {}).get('custom_languages'))
            elif sort_by == 'depth':
                val = len(PurePath(path_str).parts)
            else:
                val = path_str
            return (val, path_str)

        filtered_files.sort(key=get_extract_sort_key, reverse=sort_reverse)

    if limit > 0 and len(filtered_files) > limit:
        stats['filter_reasons']['file_limit'] = len(filtered_files) - limit
        filtered_files = filtered_files[:limit]
        stats['limit_reached'] = True

    # Apply global limits (tokens, size, lines)
    max_total_tokens = stats['max_total_tokens']
    max_total_size = stats['max_total_size_bytes']
    max_total_lines = stats['max_total_lines']

    limited_files = []
    current_tokens = 0
    current_size = 0
    current_lines = 0

    for i, item in enumerate(filtered_files):
        path_str, file_content, meta = item

        file_tokens = (meta.get('tokens') or 0)
        file_size = meta['size']
        file_lines = meta['lines']

        if max_total_tokens > 0 and (current_tokens + file_tokens) > max_total_tokens and current_tokens > 0:
            stats['token_limit_reached'] = True
            stats['filter_reasons']['token_limit'] = len(filtered_files) - i
            break

        if max_total_size > 0 and (current_size + file_size) > max_total_size and current_size > 0:
            stats['size_limit_reached'] = True
            stats['filter_reasons']['size_limit'] = len(filtered_files) - i
            break

        if max_total_lines > 0 and (current_lines + file_lines) > max_total_lines and current_lines > 0:
            stats['line_limit_reached'] = True
            stats['filter_reasons']['line_limit'] = len(filtered_files) - i
            break

        current_tokens += file_tokens
        current_size += file_size
        current_lines += file_lines
        limited_files.append(item)

    filtered_files = limited_files

    # Final Stats Pass
    for path_str, file_content, meta in filtered_files:
        rel_path = PurePath(path_str)
        stats['total_files'] += 1
        ext = rel_path.suffix.lower() or '.no_extension'
        stats['files_by_extension'][ext] = stats['files_by_extension'].get(ext, 0) + 1

        stats['total_size_bytes'] += meta['size']
        stats['size_by_extension'][ext] = stats['size_by_extension'].get(ext, 0) + meta['size']

        tokens = meta.get('tokens') or 0
        lines = meta.get('lines') or 0
        _update_stats_metrics(stats, tokens, lines, meta.get('is_approx', False))
        if tokens:
            stats['tokens_by_extension'][ext] = stats['tokens_by_extension'].get(ext, 0) + tokens
        if lines:
            stats['lines_by_extension'][ext] = stats['lines_by_extension'].get(ext, 0) + lines

        lang = meta.get('language') or utils.get_language_tag(path_str, content=file_content, overrides=stats.get('custom_languages'))
        stats['top_files'].append((meta.get('tokens') or 0, meta['size'], path_str, meta.get('status'), lines, lang))

    files_to_create = filtered_files

    if list_files:
        if json_format:
            paths = [p for p, _, _ in files_to_create]
            print(json.dumps({"files": paths, "total_files": len(paths)}, indent=2))
        else:
            for path_str, _, _ in files_to_create:
                print(path_str)
        return stats

    if tree_view:
        tree_paths = [Path(source_name) / p for p, _, _ in files_to_create]
        information_lookup = {
            Path(source_name) / p: {
                'size': m['size'],
                'tokens': m.get('tokens', 0),
                'lines': m['lines'],
                'language': utils.get_language_tag(p, content=c, overrides=config.get('search', {}).get('custom_languages'))
            }
            for p, c, m in files_to_create
        }
        print(_generate_tree_string(tree_paths, Path(source_name), include_header=False, information=information_lookup))
        return stats

    if not json_format:
        logging.info("Found %d files to extract from %s", len(files_to_create), source_name)

    extracted_count = 0
    error_count = 0
    json_extracted_files = []

    extraction_bar = _progress_bar(
        files_to_create,
        desc="Extracting files",
        unit="file",
        enabled=(not json_format and _progress_enabled(dry_run))
    )

    running_size = 0
    running_lines = 0
    running_tokens = 0

    for rel_path_str, file_content, meta in extraction_bar:
        if not json_format:
            extraction_bar.set_description(f"Extracting {_truncate_path(rel_path_str, 40)}")

        if file_content is None:
            if not json_format:
                logging.info("Skipping extraction for file without content: %s", rel_path_str)
            if json_format:
                json_extracted_files.append({
                    "path": rel_path_str,
                    "target_path": None,
                    "status": "SKIPPED",
                    "reason": "no file content",
                    "size": None,
                    "lines": None,
                    "tokens": None,
                    "error": None
                })
            continue

        file_size = _to_int_or_none(meta.get('size'))
        if file_size is None and file_content is not None:
            file_size = len(file_content.encode('utf-8'))

        file_lines = _to_int_or_none(meta.get('lines'))
        if file_lines is None and file_content is not None:
            file_lines = len(file_content.splitlines())

        file_tokens = _to_int_or_none(meta.get('tokens'))

        # Security check: prevent path traversal and absolute paths across platforms.
        try:
            requested_path = Path(rel_path_str)

            if strip_components > 0:
                parts = requested_path.parts
                if len(parts) <= strip_components:
                    msg = f"Skipping path with fewer than {strip_components} components: {rel_path_str}"
                    if not json_format:
                        logging.warning("%s", msg)
                    if json_format:
                        json_extracted_files.append({
                            "path": rel_path_str,
                            "target_path": None,
                            "status": "SKIPPED",
                            "reason": msg,
                            "size": file_size,
                            "lines": file_lines,
                            "tokens": file_tokens,
                            "error": None
                        })
                    continue
                requested_path = Path(*parts[strip_components:])

            if requested_path.is_absolute() or PurePosixPath(rel_path_str).is_absolute() or PureWindowsPath(rel_path_str).is_absolute():
                msg = f"Absolute path unsafe: {rel_path_str}"
                if not json_format:
                    logging.warning("Skipping absolute path: %s", rel_path_str)
                if json_format:
                    json_extracted_files.append({
                        "path": rel_path_str,
                        "target_path": None,
                        "status": "SKIPPED",
                        "reason": msg,
                        "size": file_size,
                        "lines": file_lines,
                        "tokens": file_tokens,
                        "error": None
                    })
                continue

            if ('..' in requested_path.parts or 
                '..' in PurePosixPath(rel_path_str.replace('\\', '/')).parts or
                '..' in PureWindowsPath(rel_path_str).parts or
                ':' in rel_path_str):
                msg = f"Potentially unsafe path: {rel_path_str}"
                if not json_format:
                    logging.warning("Skipping potentially unsafe path: %s", rel_path_str)
                if json_format:
                    json_extracted_files.append({
                        "path": rel_path_str,
                        "target_path": None,
                        "status": "SKIPPED",
                        "reason": msg,
                        "size": file_size,
                        "lines": file_lines,
                        "tokens": file_tokens,
                        "error": None
                    })
                continue

            target_path = (output_folder / requested_path).resolve()
        except (ValueError, OSError) as e:
            msg = f"Invalid path: {rel_path_str}"
            if not json_format:
                logging.warning("Skipping invalid path: %s", rel_path_str)
            if json_format:
                json_extracted_files.append({
                    "path": rel_path_str,
                    "target_path": None,
                    "status": "SKIPPED",
                    "reason": msg,
                    "size": file_size,
                    "lines": file_lines,
                    "tokens": file_tokens,
                    "error": str(e)
                })
            continue

        if show_diff and target_path.exists():
            old_content, _ = read_file_best_effort(target_path)
            _print_diff(old_content, file_content, rel_path_str)

        target_path_str = target_path.as_posix()

        if dry_run:
            if not json_format:
                logging.info("[DRY RUN] Would create: %s", target_path)
            extracted_count += 1
            if json_format:
                json_extracted_files.append({
                    "path": rel_path_str,
                    "target_path": target_path_str,
                    "status": "WOULD_EXTRACT",
                    "size": file_size,
                    "lines": file_lines,
                    "tokens": file_tokens,
                    "error": None
                })
        else:
            try:
                target_path.parent.mkdir(parents=True, exist_ok=True)
                _create_backup_if_enabled(target_path, create_backups)
                target_path.write_text(file_content, encoding='utf-8')
                if meta.get('modified') is not None:
                    os.utime(target_path, (meta['modified'], meta['modified']))
                if not json_format:
                    logging.info("Extracted: %s", target_path)
                extracted_count += 1
                if json_format:
                    json_extracted_files.append({
                        "path": rel_path_str,
                        "target_path": target_path_str,
                        "status": "EXTRACTED",
                        "size": file_size,
                        "lines": file_lines,
                        "tokens": file_tokens,
                        "error": None
                    })
            except OSError as e:
                if not json_format:
                    logging.error("Failed to write %s: %s", target_path, e)
                error_count += 1
                if json_format:
                    json_extracted_files.append({
                        "path": rel_path_str,
                        "target_path": target_path_str,
                        "status": "ERROR",
                        "size": file_size,
                        "lines": file_lines,
                        "tokens": file_tokens,
                        "error": str(e)
                    })

        running_size += (file_size or 0)
        running_lines += (file_lines or 0)
        running_tokens += (file_tokens or 0)
        if not json_format:
            extraction_bar.set_postfix(size=utils.format_size(running_size), lines=f"{running_lines:,}", tokens=f"{running_tokens:,}")

    if not json_format:
        if dry_run:
            logging.info("Extraction dry run complete. %d file(s) would be created in %s", extracted_count, output_folder)
        else:
            logging.info("Extraction complete. %d files created in %s", extracted_count, output_folder)

    if json_format:
        output_report = {
            "title": "Extraction Report",
            "dry_run": dry_run,
            "output_folder": output_folder.as_posix(),
            "files": json_extracted_files,
            "summary": {
                "extracted_count": extracted_count,
                "error_count": error_count,
                "skipped_count": len(files_to_create) - extracted_count - error_count,
                "total_discovered": len(files_to_create),
                "total_size_bytes": running_size,
                "total_lines": running_lines,
                "total_tokens": running_tokens
            }
        }
        print(json.dumps(output_report, indent=2))

    return stats


def _find_backup_files(root_path: Path) -> list[Path]:
    """Find all backup files (.bak) under or at the given target path."""
    if root_path.is_file():
        if root_path.suffix == ".bak":
            return [root_path]
        elif Path(f"{root_path}.bak").is_file():
            return [Path(f"{root_path}.bak")]
        return []
    return sorted(root_path.rglob("*.bak"))


def restore_backups(targets, dry_run=False, json_format=False):
    """Scan targets recursively for .bak files and restore them."""
    if not targets:
        targets = ["."]

    restored_count = 0
    error_count = 0
    results = []

    for target in targets:
        root_path = Path(target)
        if not root_path.exists():
            if not json_format:
                logging.warning("Target folder not found: %s", target)
            continue

        backup_files = _find_backup_files(root_path)

        if not backup_files:
            if not json_format:
                logging.info("No backup files (.bak) found in '%s'.", target)
            continue

        for backup_path in backup_files:
            original_path = backup_path.with_suffix("")
            rel_path = _get_rel_path(original_path, root_path)
            rel_path_str = rel_path.as_posix()

            if dry_run:
                if not json_format:
                    logging.info("[DRY RUN] Would restore: %s", rel_path)
                restored_count += 1
                results.append({
                    "path": rel_path_str,
                    "backup_path": _get_rel_path(backup_path, root_path).as_posix(),
                    "status": "WOULD_RESTORE",
                    "error": None
                })
            else:
                try:
                    # Move the backup back to the original location, overwriting the processed file
                    shutil.move(backup_path, original_path)
                    if not json_format:
                        logging.info("Restored: %s", rel_path)
                    restored_count += 1
                    results.append({
                        "path": rel_path_str,
                        "backup_path": _get_rel_path(backup_path, root_path).as_posix(),
                        "status": "RESTORED",
                        "error": None
                    })
                except OSError as e:
                    if not json_format:
                        logging.error("Failed to restore %s: %s", rel_path, e)
                    error_count += 1
                    results.append({
                        "path": rel_path_str,
                        "backup_path": _get_rel_path(backup_path, root_path).as_posix(),
                        "status": "ERROR",
                        "error": str(e)
                    })

    if json_format:
        output = {
            "title": "Restore Backups Report",
            "dry_run": dry_run,
            "restored": results,
            "summary": {
                "restored_count": restored_count,
                "error_count": error_count,
                "total": len(results)
            }
        }
        print(json.dumps(output, indent=2))
    else:
        if restored_count > 0 or error_count > 0:
            action = "Would restore" if dry_run else "Restored"
            logging.info("%s %d files. Errors: %d", action, restored_count, error_count)
        else:
            logging.info("No files were restored.")

    return restored_count, error_count


