                            else:
                                print(f"    {line}", end="")
                        print()  # Spacer after diff
                elif status == "ORPHANED":
                    print(f"  {C_RED}{'[ORPHANED]':<12}{C_RESET}  {rel_path_str} {C_DIM}({detail}){C_RESET}")
                else:  # ERROR
                    print(f"  {C_RED}{'[ERROR]':<12}{C_RESET}  {rel_path_str} {C_DIM}({detail}){C_RESET}")

    if json_format:
