def print_ignore_patterns(query=None, json_format=False, config=None):
    """Print active ignore patterns from ignore files and configuration exclusions, optionally filtered by a query."""
    if config is None:
        config = copy.deepcopy(utils.DEFAULT_CONFIG)
        utils.validate_config(config)
    else:
        config = copy.deepcopy(config)

    search_opts = config.get('search', {}) or {}
    filter_opts = config.get('filters', {}) or {}
    exclusions = filter_opts.get('exclusions', {}) or {}

    ignore_files = list(search_opts.get('ignore_files') or [])
    default_ignore = ".sourcecombineignore"
    if default_ignore not in ignore_files and Path(default_ignore).is_file():
        ignore_files.append(default_ignore)

    categories = {}

    for ignore_file in ignore_files:
        p = Path(ignore_file)
        if p.is_file():
            patterns = utils.parse_ignore_file(p)
            if patterns:
                categories[f"Ignore File ({ignore_file})"] = patterns

    fn_ex = exclusions.get('filenames') or []
    if fn_ex:
        categories["Excluded Filenames (Config)"] = list(fn_ex)

    fold_ex = exclusions.get('folders') or []
    if fold_ex:
        categories["Excluded Folders (Config)"] = list(fold_ex)

    total_available = sum(len(pats) for pats in categories.values())
    total_matched = 0

    if json_format:
        if query:
            query_lower = query.lower()
            filtered_cats = {}
            for cat, pats in categories.items():
                matched = [p for p in pats if query_lower in p.lower()]
                if matched:
                    filtered_cats[cat] = matched
                    total_matched += len(matched)
        else:
            filtered_cats = categories
            total_matched = total_available

        output = {
            "ignore_patterns": filtered_cats,
            "total": total_matched if query else total_available
        }
        print(json.dumps(output, indent=2))
        return

    if query:
        query_lower = query.lower()
        title_suffix = f" (FILTERED BY '{query}')"
    else:
        query_lower = None
        title_suffix = ""

    print(f"\n{C_BOLD}{C_CYAN}=== ACTIVE IGNORE PATTERNS{title_suffix} ==={C_RESET}")

    for category, patterns in categories.items():
        if query_lower:
            filtered_pats = [p for p in patterns if query_lower in p.lower()]
        else:
            filtered_pats = patterns

        if filtered_pats:
            total_matched += len(filtered_pats)
            print(f"\n  {C_BOLD}{category}{C_RESET}")
            for pat in filtered_pats:
                print(f"    {C_BOLD}{C_CYAN}{pat}{C_RESET}")

    if query_lower and total_matched == 0:
        print(f"\n  {C_YELLOW}No ignore patterns matched the filter query '{query}'.{C_RESET}")

    count_label = f"Matching: {total_matched}" if query_lower else f"Total: {total_available}"
    print(f"\n  {C_BOLD}{count_label}{C_RESET} active ignore patterns supported.")

    print(f"\n{C_BOLD}{'=' * 40}{C_RESET}\n")


def export_ignore_patterns(target_path, config=None, json_format=False):
    """Export all active ignore patterns from loaded ignore files and configuration exclusions to an ignore file or stdout."""
    if config is None:
        config = copy.deepcopy(utils.DEFAULT_CONFIG)
        utils.validate_config(config)
    else:
        config = copy.deepcopy(config)

    search_opts = config.get('search', {}) or {}
    filter_opts = config.get('filters', {}) or {}
    exclusions = filter_opts.get('exclusions', {}) or {}

    ignore_files = list(search_opts.get('ignore_files') or [])
    default_ignore = ".sourcecombineignore"
    if default_ignore not in ignore_files and Path(default_ignore).is_file():
        ignore_files.append(default_ignore)

    categories = {}

    for ignore_file in ignore_files:
        p = Path(ignore_file)
        if p.is_file():
            patterns = utils.parse_ignore_file(p)
            if patterns:
                categories[f"Ignore File ({ignore_file})"] = patterns

    fn_ex = exclusions.get('filenames') or []
    if fn_ex:
        categories["Excluded Filenames (Config)"] = list(fn_ex)

    fold_ex = exclusions.get('folders') or []
    if fold_ex:
        categories["Excluded Folders (Config)"] = list(fold_ex)

    ext_ex = exclusions.get('extensions') or []
    if ext_ex:
        categories["Excluded Extensions (Config)"] = list(ext_ex)

    all_patterns = []
    seen = set()
    for pats in categories.values():
        for pat in pats:
            if pat not in seen:
                seen.add(pat)
                all_patterns.append(pat)

    target_str = str(target_path) if target_path else ".sourcecombineignore"
    is_stdout = target_str == '-'

    if not is_stdout:
        target_file = Path(target_str)
        if target_file.is_dir() or target_str.endswith(('/', '\\')):
            target_file = target_file / ".sourcecombineignore"
    else:
        target_file = None

    if json_format:
        output = {
            "exported_to": "-" if is_stdout else str(target_file.resolve() if target_file else "-"),
            "total_patterns": len(all_patterns),
            "categories": categories,
            "patterns": all_patterns,
        }
        json_bytes = json.dumps(output, indent=2) + "\n"
        if is_stdout:
            sys.stdout.write(json_bytes)
        else:
            try:
                target_file.parent.mkdir(parents=True, exist_ok=True)
                with open(target_file, "w", encoding="utf-8") as f:
                    f.write(json_bytes)
                logging.info("Active ignore patterns exported in JSON format to %s", target_file.resolve())
            except OSError as exc:
                logging.error("Could not export ignore patterns to '%s': %s", target_file, exc)
                sys.exit(1)
        return

    lines = [
        "# SourceCombine Exported Ignore Patterns",
        "# Generated automatically from active ignore files and configuration exclusions.",
        ""
    ]
    for cat_name, pats in categories.items():
        lines.append(f"# {cat_name}")
        lines.extend(pats)
        lines.append("")

    content = "\n".join(lines)

    if is_stdout:
        sys.stdout.write(content)
        return

    try:
        target_file.parent.mkdir(parents=True, exist_ok=True)
        with open(target_file, "w", encoding="utf-8") as f:
            f.write(content)
        logging.info("Active ignore patterns exported to %s", target_file.resolve())
    except OSError as exc:
        logging.error("Could not export ignore patterns to '%s': %s", target_file, exc)
        sys.exit(1)


def import_replacements(source_path, config=None):
    """Import search-and-replace rules from a JSON or YAML file (or stdin '-') into the configuration."""
    if config is None:
        return 0

    proc_conf = config.setdefault('processing', {})
    if proc_conf is None:
        proc_conf = config['processing'] = {}

    text_rules = proc_conf.setdefault('regex_replacements', [])
    if text_rules is None:
        text_rules = proc_conf['regex_replacements'] = []

    line_rules = proc_conf.setdefault('line_regex_replacements', [])
    if line_rules is None:
        line_rules = proc_conf['line_regex_replacements'] = []

    source_str = str(source_path).strip() if source_path else ""
    if not source_str:
        logging.error("No import file specified for search-and-replace rules.")
        sys.exit(1)

    content = ""
    if source_str == '-':
        try:
            content = sys.stdin.read()
        except Exception as exc:
            logging.error("Could not read search-and-replace rules from stdin: %s", exc)
            sys.exit(1)
    else:
        src_file = Path(source_str)
        if not src_file.exists() or not src_file.is_file():
            logging.error("Search-and-replace import file not found: '%s'", source_str)
            sys.exit(1)
        try:
            with open(src_file, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            logging.error("Could not read search-and-replace rules from '%s': %s", source_str, exc)
            sys.exit(1)

    data = None
    if content.strip():
        try:
            data = json.loads(content)
        except Exception:
            try:
                import yaml
                data = yaml.safe_load(content)
            except Exception as exc:
                logging.error("Could not parse search-and-replace import file (expected JSON or YAML): %s", exc)
                sys.exit(1)

    if not isinstance(data, dict):
        if isinstance(data, list):
            data = {"regex_replacements": data}
        else:
            logging.error("Invalid format in search-and-replace import file: root must be an object or array.")
            sys.exit(1)

    imported_count = 0

    new_text_rules = data.get('regex_replacements') or data.get('text_rules') or []
    if isinstance(new_text_rules, list):
        for rule in new_text_rules:
            if isinstance(rule, dict) and 'pattern' in rule and 'replacement' in rule:
                text_rules.append({'pattern': str(rule['pattern']), 'replacement': str(rule['replacement'])})
                imported_count += 1
            elif isinstance(rule, (list, tuple)) and len(rule) >= 2:
                text_rules.append({'pattern': str(rule[0]), 'replacement': str(rule[1])})
                imported_count += 1

    new_line_rules = data.get('line_regex_replacements') or data.get('line_rules') or []
    if isinstance(new_line_rules, list):
        for rule in new_line_rules:
            if isinstance(rule, dict) and 'pattern' in rule and 'replacement' in rule:
                line_rules.append({'pattern': str(rule['pattern']), 'replacement': str(rule['replacement'])})
                imported_count += 1
            elif isinstance(rule, (list, tuple)) and len(rule) >= 2:
                line_rules.append({'pattern': str(rule[0]), 'replacement': str(rule[1])})
                imported_count += 1

    logging.info("Imported %d search-and-replace rule(s) from %s.", imported_count, "stdin" if source_str == '-' else source_str)
    return imported_count


