def print_languages(query=None, json_format=False):
    """Print all supported language identifiers and their mappings, optionally filtered by a query."""
    # Group extensions and filenames by language tag
    lang_groups = {}
    for ext, lang in utils.EXTENSION_TO_LANG.items():
        lang_groups.setdefault(lang, []).append(ext)
    for name, lang in utils.FILENAME_TO_LANG.items():
        lang_groups.setdefault(lang, []).append(name)

    if json_format:
        if query:
            query_lower = query.lower()
            lang_groups = {
                tag: items for tag, items in lang_groups.items()
                if query_lower in tag.lower() or any(query_lower in item.lower() for item in items)
            }

        output = {
            "languages": {tag: sorted(items) for tag, items in lang_groups.items()},
            "total": len(lang_groups)
        }
        print(json.dumps(output, indent=2))
        return

    if query:
        query_lower = query.lower()
        title_suffix = f" (FILTERED BY '{query}')"
    else:
        query_lower = None
        title_suffix = ""

    print(f"\n{C_BOLD}{C_CYAN}=== SUPPORTED LANGUAGES{title_suffix} ==={C_RESET}")

    # Format the output as a table
    lang_tags = sorted(lang_groups.keys())
    if query_lower:
        lang_tags = [
            tag for tag in lang_tags
            if query_lower in tag.lower() or any(query_lower in item.lower() for item in lang_groups[tag])
        ]

    tag_width = 15
    desc_width = max(40, shutil.get_terminal_size((80, 20)).columns - tag_width - 6)

    if query_lower and len(lang_tags) == 0:
        print(f"\n  {C_YELLOW}No languages matched the filter query '{query}'.{C_RESET}")
    else:
        print(f"  {C_DIM}{'LANGUAGE TAG':<{tag_width}}  EXTENSION / FILENAME MAPPINGS{C_RESET}")
        for tag in lang_tags:
            items = sorted(lang_groups[tag])
            items_str = ", ".join(items)

            # Wrap long lists of extensions
            wrapped = textwrap.wrap(items_str, width=desc_width)

            # Print the first line with the tag
            first_line = wrapped[0] if wrapped else ""
            print(f"  {C_BOLD}{C_CYAN}{tag:<{tag_width}}{C_RESET}  {C_DIM}{first_line}{C_RESET}")

            # Print subsequent lines indented
            for line in wrapped[1:]:
                print(f"  {' ':<{tag_width}}  {C_DIM}{line}{C_RESET}")

    count_label = f"Matching: {len(lang_tags)}" if query_lower else f"Total: {len(lang_groups)}"
    print(f"\n  {C_BOLD}{count_label}{C_RESET} languages supported.")
    print(f"\n{C_BOLD}{'=' * 40}{C_RESET}\n")


